(() => {
'use strict';
const KEY='northstar.personal.v3';
const $=id=>document.getElementById(id);
const localKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>localKey(new Date());
const uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:state.preferences.currency||'NZD',maximumFractionDigits:2}).format(Number(n)||0);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'short'}):'';
const monthNow=today().slice(0,7);
const recipes=[
{id:'butter-chicken',name:'Mild butter chicken',category:'Chicken',serves:4,prep:15,cook:30,description:'Creamy, gently spiced curry with rice. Keep the heat low and adjust to taste.',ingredients:['700 g boneless chicken, diced','1 tbsp oil','1 onion, finely diced','2 cloves garlic, crushed','1 tbsp grated ginger','2 tbsp mild curry powder','2 tbsp tomato paste','400 g canned crushed tomatoes','200 ml cream or coconut cream','1 tsp sugar (optional)','3 cups cooked rice, to serve','Salt to taste'],steps:['Cook rice according to its packet instructions.','Heat oil in a large pan over medium heat. Cook onion for 5–7 minutes until soft.','Add garlic, ginger and curry powder; stir for 30 seconds.','Add chicken and cook, stirring, until the outside is no longer pink.','Stir in tomato paste and crushed tomatoes. Simmer gently for 15–18 minutes, until chicken is cooked through.','Stir in cream and optional sugar. Warm gently for 3–4 minutes without boiling hard. Season and serve with rice.'],time:'45 min'},
{id:'satay-chicken',name:'Easy chicken satay rice bowls',category:'Chicken',serves:4,prep:15,cook:20,description:'A creamy peanut sauce, tender chicken and rice. Thin the sauce with water as needed.',ingredients:['600 g chicken thigh or breast, sliced','2 cups uncooked rice','3 tbsp smooth peanut butter','2 tbsp soy sauce (use gluten-free tamari if needed)','1 tbsp sweet chilli sauce, optional','1 tbsp lime juice or lemon juice','1 tsp honey','120 ml warm water','1 tbsp oil','1 cucumber or carrot, sliced'],steps:['Cook rice following packet instructions.','Mix peanut butter, soy sauce, chilli sauce if using, citrus juice, honey and warm water until smooth.','Heat oil in a large pan. Cook chicken in batches until browned and cooked through.','Pour in the sauce and simmer for 2–3 minutes. Add a splash of water if it becomes too thick.','Serve chicken and sauce over rice with sliced cucumber or carrot.'],time:'35 min'},
{id:'beef-stroganoff',name:'Slow-cooker beef stroganoff',category:'Beef',serves:4,prep:20,cook:6,description:'Comforting, low-effort beef with mushrooms and a creamy finish.',ingredients:['800 g stewing beef, sliced or cubed','1 onion, sliced','250 g mushrooms, sliced','2 cloves garlic, crushed','2 tbsp tomato paste','2 tsp paprika','300 ml beef stock','1 tbsp Worcestershire sauce','150 g sour cream','1 tbsp cornflour mixed with 2 tbsp cold water (optional)','Pasta, rice or mash, to serve'],steps:['Put beef, onion, mushrooms, garlic, tomato paste, paprika, stock and Worcestershire sauce into the slow cooker. Stir.','Cook on LOW for 7–8 hours or HIGH for 4–5 hours, until beef is tender. Slow cookers vary; use tenderness as the guide.','If the sauce needs thickening, stir in the cornflour slurry and cook on HIGH for 10–15 minutes.','Turn off the heat and let the mixture stop bubbling vigorously. Stir in sour cream. Do not boil after adding sour cream.','Serve with cooked pasta, rice or mashed potato.'],time:'7–8 hr slow cooker'},
{id:'sausage-traybake',name:'Sausage & vegetable tray bake',category:'Pork',serves:4,prep:15,cook:40,description:'A simple oven dinner with very little washing up.',ingredients:['8 sausages','600 g potatoes, cut into chunks','2 carrots, cut into batons','1 red onion, cut into wedges','2 tbsp oil','1 tsp dried mixed herbs','Salt and pepper','Frozen peas or green beans, to serve'],steps:['Heat oven to 200°C (180°C fan). Line a large roasting tray.','Toss potatoes, carrots and onion with oil, herbs, salt and pepper. Spread out.','Roast for 20 minutes, then turn the vegetables.','Add sausages to the tray and roast for another 20–25 minutes, turning once, until sausages are fully cooked and vegetables are tender.','Serve with steamed peas or green beans. Check sausages are cooked through before serving.'],time:'55 min'},
{id:'tuna-pasta',name:'Creamy tuna pasta',category:'Seafood',serves:4,prep:10,cook:15,description:'Pantry-friendly pasta with tuna and a simple creamy sauce.',ingredients:['350 g pasta','2 x 185 g cans tuna, drained','1 tbsp butter or oil','2 cloves garlic, finely chopped','200 ml milk','100 g grated cheese','1 tsp lemon juice','Frozen peas, optional','Salt and pepper'],steps:['Cook pasta in salted water according to packet instructions. Add peas for the last 3 minutes if using. Reserve a mug of pasta water, then drain.','Melt butter in the pot over low heat. Add garlic and cook for 30 seconds.','Add milk and cheese, stirring until melted. Loosen with a splash of pasta water.','Fold through tuna, lemon juice and drained pasta. Heat gently until hot.','Season to taste and serve.'],time:'25 min'},
{id:'chicken-fried-rice',name:'Quick chicken fried rice',category:'Chicken',serves:4,prep:15,cook:12,description:'A useful way to use cold cooked rice and leftover chicken.',ingredients:['4 cups cold cooked rice','300 g cooked chicken, chopped','2 eggs, beaten','1 carrot, diced small','1 cup frozen peas','2 tbsp soy sauce (or gluten-free tamari)','1 tbsp oil','2 spring onions, sliced, optional'],steps:['Break up cold rice with a fork. If cooking rice fresh, spread it on a tray and cool promptly before refrigerating.','Heat half the oil in a large pan or wok. Scramble eggs until just set; remove to a plate.','Add remaining oil and carrot; cook for 3 minutes. Add peas and chicken, heating until steaming hot.','Add rice and soy sauce. Stir-fry for 4–5 minutes, breaking up clumps and making sure everything is piping hot.','Fold the egg back in, top with spring onion if using, and serve immediately.'],time:'27 min'},
{id:'lentil-curry',name:'Mild coconut lentil curry',category:'Vegetarian',serves:4,prep:10,cook:25,description:'Budget-friendly, filling and easy to keep mild.',ingredients:['1 tbsp oil','1 onion, diced','2 cloves garlic, crushed','1 tbsp mild curry powder','1 cup red lentils, rinsed','1 x 400 ml can coconut milk','1 x 400 g can chopped tomatoes','2 cups water or vegetable stock','Salt to taste','Rice, to serve'],steps:['Heat oil in a saucepan and cook onion for 5 minutes until soft.','Add garlic and curry powder; stir for 30 seconds.','Add lentils, coconut milk, tomatoes and water or stock. Stir well.','Bring to a gentle simmer and cook uncovered for 20–25 minutes, stirring often, until lentils are soft. Add water if too thick.','Season to taste and serve with rice.'],time:'35 min'},
{id:'beef-tacos',name:'Easy beef taco bowls',category:'Beef',serves:4,prep:10,cook:15,description:'Customisable bowls with mild beef mince and simple toppings.',ingredients:['500 g beef mince','1 tbsp oil','1 tsp paprika','1 tsp cumin','1/2 tsp garlic powder','1/2 cup water','2 cups cooked rice or 8 taco shells','1 tomato, diced','1 cup grated cheese','Lettuce, corn-free salsa or yoghurt, to serve'],steps:['Heat oil in a frying pan over medium-high heat. Add mince and break it up with a wooden spoon.','Cook until browned with no pink remaining; drain excess fat if needed.','Add paprika, cumin, garlic powder and water. Simmer for 4–5 minutes until saucy.','Prepare rice or warm taco shells.','Serve with tomato, cheese, lettuce and your chosen toppings. Keep toppings separate for easy customisation.'],time:'25 min'},
{id:'roast-chicken',name:'Simple roast chicken dinner',category:'Chicken',serves:4,prep:20,cook:90,description:'A whole roast chicken with potatoes and carrots. Timing depends on bird size.',ingredients:['1 whole chicken (about 1.5–1.8 kg)','1 kg potatoes, chopped','3 carrots, chopped','1 onion, quartered','2 tbsp oil or softened butter','1 tsp dried thyme or mixed herbs','Salt and pepper','Optional: lemon halves and garlic cloves'],steps:['Heat oven to 200°C (180°C fan). Remove any giblets from the cavity and pat chicken dry.','Rub chicken with oil or butter, herbs, salt and pepper. Place onion and optional lemon/garlic inside the cavity if desired.','Put chicken breast-side up in a roasting dish. Roast for approximately 20 minutes per 500 g plus 20 minutes, but use a thermometer to confirm safety.','After about 30 minutes, add potatoes and carrots around the chicken, turning them in the pan juices.','Chicken is ready when the thickest part reaches 75°C and juices run clear. Rest for 10–15 minutes before carving.','Serve with roasted vegetables. Refrigerate leftovers within 2 hours; the carcass can be used for stock.'],time:'1 hr 45 min'},
{id:'tomato-pasta',name:'One-pot tomato pasta',category:'Vegetarian',serves:4,prep:10,cook:20,description:'An easy, low-cost dinner from basic pantry ingredients.',ingredients:['350 g pasta','1 tbsp oil','1 onion, finely diced','2 cloves garlic, crushed','2 tbsp tomato paste','1 x 400 g can chopped tomatoes','750 ml vegetable stock or water','1 tsp dried oregano','100 g grated cheese, optional','Salt and pepper'],steps:['Heat oil in a large pot over medium heat. Cook onion for 4–5 minutes until soft.','Add garlic and tomato paste and stir for 30 seconds.','Add chopped tomatoes, stock or water, oregano and pasta. Stir well.','Simmer uncovered, stirring frequently, for 12–16 minutes or until pasta is cooked. Add small splashes of water if it becomes dry before pasta is tender.','Season and serve with cheese if desired.'],time:'30 min'},
{id:'honey-soy-chicken',name:'Honey soy chicken & rice',category:'Chicken',serves:4,prep:10,cook:20,description:'Sweet-savoury chicken with a quick pan sauce.',ingredients:['600 g chicken thighs, sliced','2 cups uncooked rice','2 tbsp soy sauce (or gluten-free tamari)','1 tbsp honey','1 tbsp lemon juice or rice vinegar','1 clove garlic, crushed','1 tsp grated ginger, optional','1 tbsp oil','Broccoli or green beans, to serve'],steps:['Cook rice according to packet instructions.','Mix soy sauce, honey, lemon juice, garlic and ginger.','Heat oil in a pan. Cook chicken until browned and cooked through.','Pour sauce into the pan and simmer for 2–3 minutes until glossy, coating the chicken. Add a splash of water if it thickens too much.','Serve with rice and steamed broccoli or green beans.'],time:'30 min'},
{id:'potato-soup',name:'Creamy potato soup',category:'Vegetarian',serves:4,prep:15,cook:30,description:'A cosy soup using inexpensive basics.',ingredients:['1 kg potatoes, peeled and diced','1 onion, diced','1 tbsp butter or oil','1 litre vegetable or chicken stock','250 ml milk','Salt and pepper','Grated cheese or chopped chives, optional'],steps:['Melt butter in a large pot and cook onion for 5 minutes until soft.','Add potatoes and stock. Bring to a boil, then simmer for 18–22 minutes until potatoes are very tender.','Mash with a potato masher for a rustic texture or carefully blend until smooth.','Stir in milk and warm gently. Add a little extra water or stock if too thick.','Season and serve with optional cheese or chives and toast.'],time:'45 min'}
];
const defaults=()=>({version:3,tasks:[],habits:[{id:uid(),title:'Drink water',logs:{}},{id:uid(),title:'Eat something proper',logs:{}},{id:uid(),title:'Reset one small area',logs:{}}],planner:{},weeklyFocus:'',transactions:[],receipts:[],meals:{},mealServings:{},shopping:[],pantry:[],cleaning:[{id:uid(),title:'Wipe kitchen benches',frequency:'Daily',done:false},{id:uid(),title:'Take rubbish out',frequency:'Weekly',done:false}],projects:[],notes:[],preferences:{name:'',currency:'NZD'}});
let state;
try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&saved.version===3?{...defaults(),...saved,mealServings:saved.mealServings||{}}:defaults();}catch{state=defaults();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved on this device';}catch(e){$('saveStatus').textContent='Storage full';toast('Could not save. Export a backup and remove large receipt photos.');}renderAll();}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400);}
function go(screen){document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id==='screen-'+screen));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.screen)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$('openSettings').addEventListener('click',()=>go('settings'));
function itemRow({title,sub='',done=false,actions='',badge=''}){return `<div class="item-row ${done?'done':''}">${done?'': ''}<div class="item-main"><div class="item-title">${escapeHTML(title)}</div>${sub?`<div class="item-sub">${escapeHTML(sub)}</div>`:''}${badge?`<div style="margin-top:5px"><span class="badge">${escapeHTML(badge)}</span></div>`:''}</div><div class="item-actions">${actions}</div></div>`;}
function button(action,id,label,cls='mini-button'){return `<button class="${cls}" data-action="${action}" data-id="${escapeHTML(id)}">${label}</button>`;}
function bindActions(root=document){root.querySelectorAll('[data-action]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>handleAction(b.dataset.action,b.dataset.id,b));});}
function handleAction(action,id,el){let list;
switch(action){case'task-toggle':{const t=state.tasks.find(x=>x.id===id);if(t)t.done=!t.done;break;}case'task-delete':state.tasks=state.tasks.filter(x=>x.id!==id);break;case'habit-toggle':{const h=state.habits.find(x=>x.id===id);if(h){h.logs[today()]=!h.logs[today()];}break;}case'habit-delete':state.habits=state.habits.filter(x=>x.id!==id);break;case'tx-delete':state.transactions=state.transactions.filter(x=>x.id!==id);break;case'receipt-delete':state.receipts=state.receipts.filter(x=>x.id!==id);break;case'shop-toggle':{const x=state.shopping.find(x=>x.id===id);if(x)x.done=!x.done;break;}case'shop-delete':state.shopping=state.shopping.filter(x=>x.id!==id);break;case'pantry-low':{const x=state.pantry.find(x=>x.id===id);if(x)x.status=x.status==='low'?'ok':'low';break;}case'pantry-delete':state.pantry=state.pantry.filter(x=>x.id!==id);break;case'clean-toggle':{const x=state.cleaning.find(x=>x.id===id);if(x)x.done=!x.done;break;}case'clean-delete':state.cleaning=state.cleaning.filter(x=>x.id!==id);break;case'project-delete':state.projects=state.projects.filter(x=>x.id!==id);break;case'note-delete':state.notes=state.notes.filter(x=>x.id!==id);break;case'project-step-add':{const p=state.projects.find(x=>x.id===id);if(p){const input=el.closest('.project-card').querySelector('.step-input');const title=input.value.trim();if(title){p.steps.push({id:uid(),title,done:false});input.value='';}}break;}case'step-toggle':{const p=state.projects.find(x=>x.id===el.dataset.project);const s=p?.steps.find(x=>x.id===id);if(s)s.done=!s.done;break;}case'step-delete':{const p=state.projects.find(x=>x.id===el.dataset.project);if(p)p.steps=p.steps.filter(x=>x.id!==id);break;}case'note-edit':{const n=state.notes.find(x=>x.id===id);if(n){$('noteTitle').value=n.title;$('noteBody').value=n.body;$('noteForm').dataset.edit=id;$('noteTitle').focus();go('notes');}return;}case'recipe-open':openRecipe(id);return;}
 persist();}
$('quickTaskForm').addEventListener('submit',e=>{e.preventDefault();const title=$('quickTask').value.trim();if(!title)return;state.tasks.unshift({id:uid(),title,due:'',priority:'Normal',done:false,created:today()});$('quickTask').value='';persist();toast('Task captured');});
$('taskForm').addEventListener('submit',e=>{e.preventDefault();state.tasks.unshift({id:uid(),title:$('taskTitle').value.trim(),due:$('taskDue').value,priority:$('taskPriority').value,done:false,created:today()});e.target.reset();persist();toast('Task added');});
let taskFilter='open';document.querySelectorAll('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{taskFilter=b.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(x=>x.classList.toggle('active',x===b));renderTasks();}));
function renderTasks(){const filtered=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done)).sort((a,b)=>(a.done-b.done)||(a.due||'9999').localeCompare(b.due||'9999'));$('tasksList').innerHTML=filtered.map(t=>`<div class="item-row ${t.done?'done':''}"><input class="check" type="checkbox" data-action="task-toggle" data-id="${t.id}" ${t.done?'checked':''} aria-label="Complete ${escapeHTML(t.title)}"><div class="item-main"><div class="item-title">${escapeHTML(t.title)}</div><div class="item-sub">${t.due?'Due '+dateLabel(t.due):'No due date'} · ${escapeHTML(t.priority)} priority</div></div><div class="item-actions">${button('task-delete',t.id,'Delete','mini-button danger')}</div></div>`).join('');bindActions($('tasksList'));}
$('habitForm').addEventListener('submit',e=>{e.preventDefault();state.habits.push({id:uid(),title:$('habitTitle').value.trim(),logs:{}});e.target.reset();persist();});
function renderHabits(){const done=state.habits.filter(h=>h.logs[today()]).length;$('habitDate').textContent=new Date().toLocaleDateString('en-NZ',{weekday:'short',day:'numeric',month:'short'});$('habitsList').innerHTML=state.habits.map(h=>`<div class="item-row"><input class="check" type="checkbox" data-action="habit-toggle" data-id="${h.id}" ${h.logs[today()]?'checked':''} aria-label="Mark ${escapeHTML(h.title)} done"><div class="item-main"><div class="item-title">${escapeHTML(h.title)}</div><div class="item-sub">${h.logs[today()]?'Done today':'One small check-in'}</div></div>${button('habit-delete',h.id,'×','mini-button')}</div>`).join('');bindActions($('habitsList'));const hist=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=localKey(d);const n=state.habits.filter(h=>h.logs[key]).length;return `<div class="history-day">${d.toLocaleDateString('en-NZ',{weekday:'short'}).slice(0,2)}<div class="history-dot ${n?'has':''}">${n?`${n}/${state.habits.length}`:'·'}</div></div>`}).join('');$('habitHistory').innerHTML=hist;return state.habits.length?Math.round(done/state.habits.length*100):0;}
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
$('weeklyFocus').value=state.weeklyFocus||'';$('weeklyFocus').addEventListener('change',e=>{state.weeklyFocus=e.target.value;persist();});
function renderPlanner(){const base=new Date();const dow=(base.getDay()+6)%7;const monday=new Date(base);monday.setDate(base.getDate()-dow);$('weekPlanner').innerHTML=days.map((d,i)=>{const dt=new Date(monday);dt.setDate(monday.getDate()+i);const key=localKey(dt);return `<div class="day-plan"><div class="day-label">${d}<small>${dt.toLocaleDateString('en-NZ',{day:'numeric',month:'short'})}</small></div><textarea data-plan-date="${key}" placeholder="Plans, appointments, reminders…">${escapeHTML(state.planner[key]||'')}</textarea></div>`}).join('');$('weekPlanner').querySelectorAll('textarea').forEach(t=>t.addEventListener('change',()=>{state.planner[t.dataset.planDate]=t.value;persist();}));}
$('clearWeek').addEventListener('click',()=>{if(!confirm('Clear the notes for this week?'))return;const base=new Date();base.setDate(base.getDate()-((base.getDay()+6)%7));for(let i=0;i<7;i++){const d=new Date(base);d.setDate(base.getDate()+i);delete state.planner[localKey(d)];}renderPlanner();persist();});
$('transactionForm').addEventListener('submit',e=>{e.preventDefault();const type=$('txType').value;state.transactions.unshift({id:uid(),date:$('txDate').value,description:$('txDescription').value.trim(),amount:Number($('txAmount').value),type,category:$('txCategory').value,source:'manual'});e.target.reset();$('txDate').value=today();persist();toast('Transaction saved');});
function normaliseCategory(text,type){const s=text.toLowerCase();if(type==='income'||/wage|salary|payroll|benefit|ird refund/.test(s))return'Income';if(/fuel|petrol|diesel|uber|bus|metro|parking/.test(s))return'Transport';if(/rent|board|mortgage/.test(s))return'Housing';if(/power|electric|internet|wifi|phone|insurance|subscription|netflix|spotify/.test(s))return'Bills';if(/woolworth|countdown|new world|pak.?n.?save|supermarket|grocery|food|cafe|restaurant|takeaway/.test(s))return'Food';if(/doctor|pharmacy|medical|chemist/.test(s))return'Health';if(/game|xbox|playstation|steam|cinema/.test(s))return'Entertainment';if(/transfer|payment to|payment from/.test(s))return'Transfer';if(/warehouse|kmart|amazon|shopping/.test(s))return'Shopping';return'Other';}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'){row.push(field);rows.push(row);row=[];field='';}else if(c!=='\r')field+=c;}if(field.length||row.length){row.push(field);rows.push(row);}return rows.filter(r=>r.some(c=>String(c).trim()));}
function parseDate(s){s=String(s||'').trim();if(!s)return'';let m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);if(m){let a=+m[1],b=+m[2],y=+m[3];if(y<100)y+=2000;return a>12?`${y}-${String(b).padStart(2,'0')}-${String(a).padStart(2,'0')}`:`${y}-${String(a).padStart(2,'0')}-${String(b).padStart(2,'0')}`;}const d=new Date(s);return isNaN(d)?'':localKey(d);}
function cleanStatementAmount(raw){let s=String(raw||'').replace(/\bNZD\b/ig,'').replace(/[$,\s]/g,'');const negative=/\(|-|\bDR\b/i.test(raw);s=s.replace(/[()]/g,'').replace(/\b(?:DR|CR)\b/ig,'');const n=Number(s);return Number.isFinite(n)?(negative?-Math.abs(n):Math.abs(n)):0;}
function statementDateAtStart(text){const s=String(text||'').trim();let m=s.match(/^(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}|\d{4}-\d{2}-\d{2}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4})\b/);if(!m)return'';let raw=m[1];if(/^\d{1,2}\s+[A-Za-z]/.test(raw)){const d=new Date(raw);return isNaN(d)?'':localKey(d);}return parseDate(raw);}
async function extractPDFStatement(file){if(!window.pdfjsLib)throw Error('The PDF reader could not load. Connect to the internet, reload Northstar, and try again. CSV import is still available.');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const lines=[];for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();const buckets=[];for(const item of content.items){if(!item.str||!item.str.trim()||!item.transform)continue;const x=item.transform[4],y=item.transform[5];let line=buckets.find(l=>Math.abs(l.y-y)<2.5);if(!line){line={y,items:[]};buckets.push(line);}line.items.push({x,text:item.str.trim()});}buckets.sort((a,b)=>b.y-a.y);for(const line of buckets){line.items.sort((a,b)=>a.x-b.x);const text=line.items.map(i=>i.text).join(' ').replace(/\s+/g,' ').trim();if(text)lines.push(text);}}return lines;}
function parsePDFStatementLines(lines){const candidates=[];const amountRx=/(?<![\w/])(?:NZD\s*)?(?:\$\s*)?\(?-?\d[\d,]*\.\d{2}\)?(?:\s*(?:DR|CR))?(?!\w)/ig;let current=null;for(const line of lines){const date=statementDateAtStart(line);if(date){if(current)candidates.push(current);current={date,text:line.replace(/^(?:\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}|\d{4}-\d{2}-\d{2}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4})\s*/,'').trim()};}else if(current&&!/^(?:opening|closing|available|ledger|statement|page\s+\d|date\s+description|transaction date)/i.test(line)){current.text+=' '+line;}}if(current)candidates.push(current);const output=[];for(const row of candidates){const matches=[...row.text.matchAll(amountRx)];if(!matches.length)continue;const last=matches[matches.length-1];let amountToken=last[0];let description=row.text.slice(0,last.index).trim();let amount=cleanStatementAmount(amountToken);if(matches.length>=2){const prior=matches[matches.length-2];const priorText=prior[0];const lastText=last[0];const tail=row.text.slice(last.index+lastText.length);const isBalance=/balance/i.test(tail)||/balance/i.test(row.text);if(!isBalance){amountToken=priorText;amount=cleanStatementAmount(amountToken);description=row.text.slice(0,prior.index).trim();}else{amountToken=priorText;amount=cleanStatementAmount(amountToken);description=row.text.slice(0,prior.index).trim();}}description=description.replace(/[|•·]+$/g,'').replace(/\s{2,}/g,' ').trim();description=description.replace(/\b(?:NZD\s*)?\$?\(?-?\d[\d,]*\.\d{2}\)?\s*(?:DR|CR)?\s*$/i,'').trim();if(!description||!amount)continue;const token=String(amountToken||'');const isCredit=/\bCR\b/i.test(token)||/\b(salary|wages|payroll|benefit|deposit|refund|interest received|payment received|credit|ird refund)\b/i.test(description);const isDebit=/\bDR\b/i.test(token)||/\b(purchase|eftpos|withdrawal|payment to|direct debit|fee|charge)\b/i.test(description);let type=(/\(|-/.test(token)||isDebit)?'expense':isCredit?'income':'expense';const dupe=output.some(t=>t.date===row.date&&t.description.toLowerCase()===description.toLowerCase()&&t.amount===Math.abs(amount));if(!dupe)output.push({date:row.date,description,amount:Math.abs(amount),type});}return output;}
$('csvFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{let fresh=[],skipped=0;if(file.name.toLowerCase().endsWith('.pdf')||file.type==='application/pdf'){const lines=await extractPDFStatement(file);fresh=parsePDFStatementLines(lines).map(t=>({...t,id:uid(),category:normaliseCategory(t.description,t.type),source:'pdf'}));if(!fresh.length)throw Error('I could not confidently find transaction rows in this PDF. It may be scanned, password-protected, or use an unsupported layout. Try downloading a text-based PDF or use your bank’s CSV export.');}else{const rows=parseCSV(await file.text());if(rows.length<2)throw Error('The CSV appears to be empty.');const headers=rows[0].map(x=>x.toLowerCase().trim().replace(/[ _-]+/g,''));const find=(...keys)=>headers.findIndex(h=>keys.includes(h));const di=find('date','transactiondate','processeddate','valuedate');const desc=find('description','details','payee','particulars','transaction','memo','name');const ai=find('amount','transactionamount','value');const wi=find('withdrawal','withdrawals','debit','moneyout');const ci=find('deposit','deposits','credit','moneyin');const cat=find('category','type');if(di<0||desc<0||(ai<0&&wi<0&&ci<0))throw Error('Could not recognise columns. Include Date, Description and Amount, or separate Withdrawal/Deposit columns.');for(const r of rows.slice(1)){const date=parseDate(r[di]);const description=String(r[desc]||'').trim();if(!date||!description){skipped++;continue;}let amount=0,type='expense';if(ai>=0){const raw=String(r[ai]||'').replace(/[,$\s]/g,'').replace(/[()]/g,'');amount=Number(raw);if(String(r[ai]).includes('('))amount=-Math.abs(amount);if(amount<0){type='expense';amount=Math.abs(amount);}else type='income';}else{const w=Number(String(r[wi]||'0').replace(/[,$\s]/g,''))||0;const c=Number(String(r[ci]||'0').replace(/[,$\s]/g,''))||0;if(w){amount=Math.abs(w);type='expense';}else{amount=Math.abs(c);type='income';}}if(!Number.isFinite(amount)||amount<=0){skipped++;continue;}const typeCol=cat>=0?String(r[cat]||'').toLowerCase():'';if(typeCol.includes('credit')||typeCol.includes('deposit'))type='income';if(typeCol.includes('debit')||typeCol.includes('withdraw'))type='expense';fresh.push({id:uid(),date,description,amount,type,category:normaliseCategory(description,type),source:'csv'});}}
const before=fresh.length;fresh=fresh.filter(t=>!state.transactions.some(x=>x.date===t.date&&x.description.toLowerCase()===t.description.toLowerCase()&&Number(x.amount)===Number(t.amount)));skipped+=before-fresh.length;if(!fresh.length)throw Error('No new transactions were imported. The statement may contain no readable transactions, or these entries may already exist.');state.transactions.unshift(...fresh);persist();$('importNotice').textContent=`Imported ${fresh.length} transaction(s) from ${file.name}; skipped ${skipped} invalid or duplicate row(s). PDF layouts can be ambiguous: verify dates, descriptions, debit/credit direction and amounts before relying on totals.`;toast(`${fresh.length} transactions imported`);}catch(err){$('importNotice').textContent=err.message||'Could not import this statement.';toast('Statement import needs checking');}e.target.value='';});
$('downloadTemplate').addEventListener('click',()=>download('northstar-transactions-template.csv','Date,Description,Amount\n2026-10-01,Example grocery shop,-45.20\n2026-10-02,Example income,120.00\n'));
$('txSearch').addEventListener('input',renderTransactions);
function getMonthTransactions(){return state.transactions.filter(t=>(t.date||'').slice(0,7)===monthNow);}
function recurringCandidates(){const map={};state.transactions.filter(t=>t.type==='expense').forEach(t=>{const key=t.description.toLowerCase().replace(/[0-9#*]/g,'').replace(/\s+/g,' ').trim();if(!key)return;(map[key]??=[]).push(t);});return Object.entries(map).map(([key,items])=>({key,items,months:new Set(items.map(t=>t.date.slice(0,7))).size,avg:items.reduce((s,t)=>s+Number(t.amount),0)/items.length,last:items.sort((a,b)=>b.date.localeCompare(a.date))[0]})).filter(x=>x.months>=2||x.items.length>=3).sort((a,b)=>b.months-a.months||b.items.length-a.items.length).slice(0,8);}
function renderTransactions(){const q=($('txSearch')?.value||'').toLowerCase();const list=state.transactions.filter(t=>`${t.description} ${t.category} ${t.date}`.toLowerCase().includes(q)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));$('transactionsList').innerHTML=list.slice(0,100).map(t=>itemRow({title:t.description,sub:`${dateLabel(t.date)} · ${t.category} · ${(t.source==='csv'||t.source==='pdf')?'Imported':'Manual'}`,badge:t.type==='income'?'Income':'Expense',actions:`<b class="${t.type==='income'?'good':'bad'}">${t.type==='income'?'+':'−'}${money(t.amount)}</b>${button('tx-delete',t.id,'×','mini-button')}`})).join('');bindActions($('transactionsList'));const m=getMonthTransactions();const income=m.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0);const out=m.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);$('moneyIncome').textContent=money(income);$('moneyOut').textContent=money(out);$('moneyNet').textContent=money(income-out);const rec=recurringCandidates();$('moneyRecurring').textContent=rec.length;$('recurringList').innerHTML=rec.map(r=>itemRow({title:r.last.description,sub:`Seen in ${r.months} month(s) · ${r.items.length} transactions · average ${money(r.avg)}`,badge:'Possible recurring',actions:`<b>${money(r.avg)}</b>`})).join('')||'<div class="empty-state">Not enough repeated transactions yet. Import a few months of history to look for patterns.</div>';}
$('receiptForm').addEventListener('submit',async e=>{e.preventDefault();const file=$('receiptImage').files[0];let image='';if(file){if(file.size>8*1024*1024){toast('Choose an image under 8 MB');return;}try{image=await resizeImage(file);}catch{toast('Could not read that image');return;}}state.receipts.unshift({id:uid(),date:$('receiptDate').value,store:$('receiptStore').value.trim(),amount:Number($('receiptAmount').value),image});e.target.reset();$('receiptDate').value=today();persist();toast('Receipt saved');});
function resizeImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,900/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.68));};img.src=reader.result;};reader.readAsDataURL(file);});}
function renderReceipts(){$('receiptsList').innerHTML=state.receipts.map(r=>`<div class="item-row">${r.image?`<img class="receipt-thumb" src="${r.image}" alt="Receipt">`:''}<div class="item-main"><div class="item-title">${escapeHTML(r.store)}</div><div class="item-sub">${dateLabel(r.date)} · ${money(r.amount)}</div></div><div class="item-actions">${button('receipt-delete',r.id,'×','mini-button')}</div></div>`).join('');bindActions($('receiptsList'));}
$('mealPlanner').addEventListener('change',e=>{
 if(e.target.matches('[data-meal-day]')){
  const key=e.target.dataset.mealDay;state.meals[key]=e.target.value;
  const recipe=recipes.find(r=>r.id===e.target.value);
  if(recipe&&!state.mealServings[key])state.mealServings[key]=recipe.serves;
  if(!recipe)delete state.mealServings[key];
  persist();
 }
 if(e.target.matches('[data-meal-servings]')){state.mealServings[e.target.dataset.mealServings]=Number(e.target.value);persist();}
});
function renderMeals(){const base=new Date();base.setDate(base.getDate()-((base.getDay()+6)%7));$('mealPlanner').innerHTML=days.map((d,i)=>{const dt=new Date(base);dt.setDate(base.getDate()+i);const key=localKey(dt);const current=state.meals[key]||'';const recipe=recipes.find(r=>r.id===current);const servings=Number(state.mealServings[key]||recipe?.serves||4);return `<div class="meal-day"><div class="meal-day-label">${d}<div class="meal-note">${dt.toLocaleDateString('en-NZ',{day:'numeric',month:'short'})}</div></div><div class="meal-choice"><select data-meal-day="${key}" aria-label="Meal for ${d}"><option value="">Choose a meal…</option>${recipes.map(r=>`<option value="${r.id}" ${current===r.id?'selected':''}>${escapeHTML(r.name)}</option>`).join('')}<option value="custom" ${current==='custom'?'selected':''}>Something else / leftovers</option></select>${recipe?`<label class="meal-servings-label">Servings <select data-meal-servings="${key}" aria-label="Servings for ${d}">${[1,2,3,4,5,6,8,10,12].map(n=>`<option value="${n}" ${servings===n?'selected':''}>${n}</option>`).join('')}</select></label>`:''}<div class="meal-note">${recipe?escapeHTML(recipe.time):current==='custom'?'Flexible meal':''}</div></div></div>`;}).join('');}
function fractionValue(v){if(v==='½')return .5;if(v==='¼')return .25;if(v==='¾')return .75;if(v==='⅓')return 1/3;if(v==='⅔')return 2/3;if(v.includes('/')){const a=v.split('/').map(Number);return a[1]?a[0]/a[1]:0;}return Number(v);}
function parseMealIngredient(raw,scale){
 let text=String(raw).trim().replace(/^optional:\s*/i,'');
 const start=/^(\d+(?:\.\d+)?|\d+\/\d+|[½¼¾⅓⅔])(?:\s+(\d+\/\d+|[½¼¾⅓⅔]))?\s*(.*)$/u.exec(text);
 if(!start)return {key:text.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),name:text,quantity:null,unit:'',scaled:false,optional:/optional/i.test(raw)};
 let qty=fractionValue(start[1])+(start[2]?fractionValue(start[2]):0);let rest=start[3].trim();
 // Preserve pack size while combining identical packs (e.g. cans of the same size).
 const pack=/^(?:x\s*)?(\d+(?:\.\d+)?)\s*(g|kg|ml|l)\s+(?:cans?|tins?|cartons?)\s+(.+)$/i.exec(rest);
 let unit='',name='';
 if(pack){unit=`can (${pack[1]} ${pack[2].toLowerCase()})`;name=pack[3];}
 else {
  const u=/^(kg|g|ml|l|tbsp|tsp|cups?|cloves?|cans?|tins?|eggs?|slices?|tablespoons?|teaspoons?|bunch(?:es)?|packets?|packs?|sachets?|servings?|whole)\b\s*(.*)$/i.exec(rest);
  if(u){unit=u[1].toLowerCase().replace(/^cups?$/,'cup').replace(/^tablespoons?$/,'tbsp').replace(/^teaspoons?$/,'tsp').replace(/^cloves?$/,'clove').replace(/^cans?$/,'can').replace(/^tins?$/,'tin').replace(/^eggs?$/,'egg').replace(/^slices?$/,'slice').replace(/^packets?$/,'packet').replace(/^packs?$/,'pack').replace(/^bunches$/,'bunch').replace(/^servings?$/,'serving');name=u[2].trim();}
  else {unit='each';name=rest;}
 }
 // Remove common preparation notes from the grouping key, but keep meaningful descriptors.
 name=name.replace(/,\s*(finely diced|diced|sliced|crushed|chopped|drained|rinsed|quartered|to serve|optional|cut into .+)$/i,'').trim();
 const key=(unit+' '+name).toLowerCase().replace(/[^a-z0-9()]+/g,' ').trim();
 return {key,name:name||rest,quantity:qty*scale,unit,scaled:true,optional:/optional/i.test(raw)};
}
function formatQuantity(n){if(Math.abs(n-Math.round(n))<.02)return String(Math.round(n));return (Math.round(n*100)/100).toFixed(2).replace(/0+$/,'').replace(/\.$/,'');}
function currentWeekDates(){const base=new Date();base.setDate(base.getDate()-((base.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()+i);return localKey(d);});}
function buildMealProposal(){const grouped=new Map();for(const date of currentWeekDates()){const recipe=recipes.find(r=>r.id===state.meals[date]);if(!recipe)continue;const scale=Number(state.mealServings[date]||recipe.serves)/recipe.serves;for(const raw of recipe.ingredients){const ing=parseMealIngredient(raw,scale);const existing=grouped.get(ing.key);if(existing){if(existing.quantity!==null&&ing.quantity!==null&&existing.unit===ing.unit)existing.quantity+=ing.quantity;else if(existing.raws.indexOf(raw)<0){existing.raws.push(raw);existing.sources.push(recipe.name);}}else grouped.set(ing.key,{...ing,raws:[raw],sources:[recipe.name],selected:true});}}
 const manual=state.shopping.filter(x=>x.source!=='meal-plan'&&!x.done);const bought=state.shopping.filter(x=>x.source==='meal-plan'&&x.done);
 return [...grouped.values()].map(item=>{item.label=item.quantity===null?item.name:`${formatQuantity(item.quantity)} ${item.unit==='each'?'':item.unit+' '}${item.name}`.replace(/\s+/g,' ').trim();item.manualMatch=manual.find(x=>{const parsed=parseMealIngredient(x.name,1);const nameKey=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();return parsed.key===item.key||nameKey(parsed.name)===nameKey(item.name);});item.alreadyBought=bought.some(x=>x.key===item.key);return item;});}
function renderShoppingReview(){const proposal=buildMealProposal();const host=$('shoppingProposal');if(!proposal.length){host.innerHTML='<div class="empty-state">Choose at least one recipe in this week’s meal plan to generate ingredients.</div>';$('applyShoppingProposal').disabled=true;return;}$('applyShoppingProposal').disabled=false;host.innerHTML=proposal.map((x,i)=>`<label class="proposal-row ${x.manualMatch||x.alreadyBought?'proposal-muted':''}"><input type="checkbox" data-proposal-index="${i}" ${x.manualMatch||x.alreadyBought?'':'checked'} ${x.manualMatch||x.alreadyBought?'disabled':''}><span class="proposal-main"><b>${escapeHTML(x.label)}</b><small>${escapeHTML([...new Set(x.sources)].join(', '))}${x.manualMatch?' · already on your list':x.alreadyBought?' · marked bought':''}${x.optional?' · optional':''}</small></span></label>`).join('');}
$('buildShopping').addEventListener('click',()=>{renderShoppingReview();$('shoppingReviewDialog').showModal();});
$('applyShoppingProposal').addEventListener('click',()=>{const proposal=buildMealProposal();const checked=new Set([...$('shoppingProposal').querySelectorAll('[data-proposal-index]:checked')].map(x=>Number(x.dataset.proposalIndex)));const selected=proposal.filter((x,i)=>checked.has(i));
 // Rebuild only the uncompleted meal-plan-generated entries; preserve manual items and anything already checked off.
 state.shopping=state.shopping.filter(x=>x.source!=='meal-plan'||x.done);
 for(const item of selected){if(state.shopping.some(x=>!x.done&&parseMealIngredient(x.name,1).key===item.key))continue;state.shopping.push({id:uid(),name:item.label,done:false,source:'meal-plan',key:item.key,recipes:[...new Set(item.sources)]});}
 persist();$('shoppingReviewDialog').close();setFoodTab('shopping');toast(`Shopping list updated with ${selected.length} selected ingredients`);
});
$('recipeSearch').addEventListener('input',renderRecipes);
function renderRecipes(){const q=($('recipeSearch')?.value||'').toLowerCase();$('recipesList').innerHTML=recipes.filter(r=>`${r.name} ${r.category} ${r.description}`.toLowerCase().includes(q)).map(r=>`<article class="recipe-card"><span class="badge">${escapeHTML(r.category)}</span><h3>${escapeHTML(r.name)}</h3><div class="recipe-meta">${r.serves} servings · ${r.time} · ${r.prep} min prep</div><p>${escapeHTML(r.description)}</p><button class="secondary" data-action="recipe-open" data-id="${r.id}">View full recipe</button></article>`).join('');bindActions($('recipesList'));}
function openRecipe(id){const r=recipes.find(x=>x.id===id);if(!r)return;$('recipeDetail').innerHTML=`<div class="recipe-detail"><span class="badge">${escapeHTML(r.category)}</span><h2>${escapeHTML(r.name)}</h2><p class="muted">${r.serves} servings · ${r.prep} min prep · ${r.time} cooking time</p><p>${escapeHTML(r.description)}</p><div class="section-heading"><h3>Ingredients</h3><label style="display:flex;align-items:center;gap:8px;margin:0">Servings <select id="servingsAdjust" style="width:78px;padding:6px"><option>2</option><option ${r.serves===4?'selected':''}>4</option><option>6</option><option>8</option></select></label></div><ul id="recipeIngredients">${r.ingredients.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul><h3>Method</h3><ol>${r.steps.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol><div class="notice">Food safety: cook meat thoroughly and refrigerate leftovers promptly. Check labels and cross-contact risks for any dietary requirements.</div><button id="addRecipeIngredients" class="primary">Add ingredients to shopping list</button></div>`;$('recipeDialog').showModal();$('servingsAdjust').addEventListener('change',e=>{const scale=Number(e.target.value)/r.serves;$('recipeIngredients').innerHTML=r.ingredients.map(x=>{const ing=parseMealIngredient(x,scale);return `<li>${escapeHTML(ing.quantity===null?ing.name:`${formatQuantity(ing.quantity)} ${ing.unit==='each'?'':ing.unit+' '}${ing.name}`.replace(/\s+/g,' ').trim())}</li>`;}).join('');});$('addRecipeIngredients').addEventListener('click',()=>{const scale=Number($('servingsAdjust').value)/r.serves;r.ingredients.forEach(raw=>{const ing=parseMealIngredient(raw,scale);const name=ing.quantity===null?ing.name:`${formatQuantity(ing.quantity)} ${ing.unit==='each'?'':ing.unit+' '}${ing.name}`.replace(/\s+/g,' ').trim();if(!state.shopping.some(x=>parseMealIngredient(x.name,1).key===ing.key&&!x.done))state.shopping.push({id:uid(),name,done:false,source:'recipe',key:ing.key});});persist();$('recipeDialog').close();setFoodTab('shopping');toast('Ingredients added');});}
function setFoodTab(tab){document.querySelectorAll('.subtab').forEach(b=>b.classList.toggle('active',b.dataset.foodTab===tab));document.querySelectorAll('.food-pane').forEach(p=>p.classList.toggle('active',p.id==='food-'+tab));}
document.querySelectorAll('[data-food-tab]').forEach(b=>b.addEventListener('click',()=>setFoodTab(b.dataset.foodTab)));
$('shoppingForm').addEventListener('submit',e=>{e.preventDefault();state.shopping.push({id:uid(),name:$('shoppingItem').value.trim(),done:false});e.target.reset();persist();});$('clearCheckedShopping').addEventListener('click',()=>{state.shopping=state.shopping.filter(x=>!x.done);persist();});
function renderShopping(){$('shoppingList').innerHTML=state.shopping.map(x=>`<div class="item-row ${x.done?'done':''}"><input type="checkbox" class="check" data-action="shop-toggle" data-id="${x.id}" ${x.done?'checked':''} aria-label="Mark ${escapeHTML(x.name)} bought"><div class="item-main"><div class="item-title">${escapeHTML(x.name)}</div>${x.source==='meal-plan'?`<div class="item-sub">From meal plan${x.recipes?.length?` · ${escapeHTML(x.recipes.join(', '))}`:''}</div>`:''}</div><div class="item-actions">${button('shop-delete',x.id,'×','mini-button')}</div></div>`).join('');bindActions($('shoppingList'));}
$('pantryForm').addEventListener('submit',e=>{e.preventDefault();state.pantry.push({id:uid(),name:$('pantryName').value.trim(),qty:$('pantryQty').value.trim(),status:$('pantryLow').value});e.target.reset();persist();});function renderPantry(){$('pantryList').innerHTML=state.pantry.map(x=>itemRow({title:x.name,sub:x.qty||'No quantity note',badge:x.status==='low'?'Running low':'In stock',actions:`${button('pantry-low',x.id,x.status==='low'?'Mark stocked':'Mark low','mini-button')}${button('pantry-delete',x.id,'×','mini-button')}`})).join('');bindActions($('pantryList'));}
$('cleaningForm').addEventListener('submit',e=>{e.preventDefault();state.cleaning.push({id:uid(),title:$('cleaningTitle').value.trim(),frequency:$('cleaningFreq').value,done:false});e.target.reset();persist();});function renderCleaning(){$('cleaningList').innerHTML=state.cleaning.map(x=>`<div class="item-row ${x.done?'done':''}"><input type="checkbox" class="check" data-action="clean-toggle" data-id="${x.id}" ${x.done?'checked':''} aria-label="Mark ${escapeHTML(x.title)} done"><div class="item-main"><div class="item-title">${escapeHTML(x.title)}</div><div class="item-sub">${escapeHTML(x.frequency)}</div></div><div class="item-actions">${button('clean-delete',x.id,'×','mini-button')}</div></div>`).join('');bindActions($('cleaningList'));}
$('projectForm').addEventListener('submit',e=>{e.preventDefault();state.projects.unshift({id:uid(),title:$('projectTitle').value.trim(),notes:$('projectNotes').value.trim(),steps:[],created:today()});e.target.reset();persist();});function renderProjects(){$('projectsList').innerHTML=state.projects.map(p=>{const done=p.steps.filter(s=>s.done).length,percent=p.steps.length?Math.round(done/p.steps.length*100):0;return `<article class="project-card"><div class="section-heading"><h3>${escapeHTML(p.title)}</h3>${button('project-delete',p.id,'Delete','mini-button danger')}</div>${p.notes?`<p class="muted">${escapeHTML(p.notes)}</p>`:''}<div class="progress"><span style="width:${percent}%"></span></div><div class="muted">${done}/${p.steps.length} steps complete</div><div class="stack" style="margin:8px 0">${p.steps.map(s=>`<div class="item-row ${s.done?'done':''}"><input class="check" type="checkbox" data-action="step-toggle" data-id="${s.id}" data-project="${p.id}" ${s.done?'checked':''}><div class="item-main"><div class="item-title">${escapeHTML(s.title)}</div></div>${button('step-delete',s.id,'×','mini-button')}</div>`).join('')}</div><form class="inline-form add-step-form" data-project="${p.id}"><input class="step-input" placeholder="Add a next step…" maxlength="140" required><button type="button" class="secondary" data-action="project-step-add" data-id="${p.id}">Add step</button></form></article>`;}).join('');bindActions($('projectsList'));$('projectsList').querySelectorAll('.add-step-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const b=f.querySelector('button');handleAction('project-step-add',f.dataset.project,b);}));}
$('noteForm').addEventListener('submit',e=>{e.preventDefault();const id=e.target.dataset.edit;if(id){const n=state.notes.find(x=>x.id===id);if(n){n.title=$('noteTitle').value.trim();n.body=$('noteBody').value;}delete e.target.dataset.edit;}else state.notes.unshift({id:uid(),title:$('noteTitle').value.trim(),body:$('noteBody').value,updated:new Date().toISOString()});e.target.reset();persist();toast('Note saved');});function renderNotes(){$('notesList').innerHTML=state.notes.map(n=>`<article class="note-card"><div class="section-heading"><h3>${escapeHTML(n.title)}</h3><div>${button('note-edit',n.id,'Edit','mini-button')}${button('note-delete',n.id,'×','mini-button')}</div></div><div class="note-body">${escapeHTML(n.body)}</div><div class="item-sub">${n.updated?new Date(n.updated).toLocaleDateString('en-NZ'):'Saved locally'}</div></article>`).join('');bindActions($('notesList'));}
function renderHome(){const open=state.tasks.filter(t=>!t.done);$('metricTasks').textContent=open.length;$('metricDue').textContent=state.tasks.filter(t=>!t.done&&t.due&&t.due<=today()).length;$('metricHabits').textContent=state.habits.length?Math.round(state.habits.filter(h=>h.logs[today()]).length/state.habits.length*100)+'%':'—';$('metricHabitsSub').textContent=state.habits.length?`${state.habits.filter(h=>h.logs[today()]).length} of ${state.habits.length} checked in`:'Add a habit';const month=getMonthTransactions();$('metricSpend').textContent=money(month.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0));$('homeTasks').innerHTML=open.slice(0,5).map(t=>`<div class="item-row"><input type="checkbox" class="check" data-action="task-toggle" data-id="${t.id}" aria-label="Complete task"><div class="item-main"><div class="item-title">${escapeHTML(t.title)}</div><div class="item-sub">${t.due?'Due '+dateLabel(t.due):'No due date'}</div></div></div>`).join('');bindActions($('homeTasks'));$('homeHabitsList').innerHTML=state.habits.slice(0,5).map(h=>`<div class="item-row"><input type="checkbox" class="check" data-action="habit-toggle" data-id="${h.id}" ${h.logs[today()]?'checked':''} aria-label="Complete habit"><div class="item-main"><div class="item-title">${escapeHTML(h.title)}</div></div></div>`).join('');bindActions($('homeHabitsList'));$('homeTransactions').innerHTML=state.transactions.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,4).map(t=>itemRow({title:t.description,sub:dateLabel(t.date),actions:`<b class="${t.type==='income'?'good':'bad'}">${t.type==='income'?'+':'−'}${money(t.amount)}</b>`})).join('');const upcoming=Object.entries(state.meals).filter(([date,id])=>date>=today()&&id).sort((a,b)=>a[0].localeCompare(b[0])).slice(0,4);$('homeComing').innerHTML=upcoming.map(([date,id])=>{const r=recipes.find(r=>r.id===id);return itemRow({title:r?r.name:'Planned meal',sub:dateLabel(date)});}).join('')||'<div class="empty-state">No meals planned yet. A couple of ideas is enough to start.</div>';const name=state.preferences.name?`, ${escapeHTML(state.preferences.name)}`:'';document.querySelector('.welcome h1').textContent=state.preferences.name?`Make today manageable${name}.`:'Make today manageable.';}
function renderAll(){renderTasks();renderPlanner();const pct=renderHabits();renderTransactions();renderReceipts();renderMeals();renderRecipes();renderShopping();renderPantry();renderCleaning();renderProjects();renderNotes();renderHome();}
function download(filename,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
$('exportData').addEventListener('click',()=>{download(`northstar-backup-${today()}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'Northstar Personal Workspace'},null,2),'application/json');$('backupStatus').textContent='Backup export started. Store the downloaded file somewhere safe.';});
$('restoreFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data||typeof data!=='object'||!Array.isArray(data.tasks)||!Array.isArray(data.transactions))throw Error('This does not look like a Northstar backup.');if(!confirm('Restore this backup and replace the current workspace data? Export your current data first if needed.'))return;state={...defaults(),...data,version:3};persist();$('backupStatus').textContent='Backup restored into this browser.';toast('Backup restored');}catch(err){$('backupStatus').textContent=err.message||'Could not restore backup.';}e.target.value='';});
$('savePreferences').addEventListener('click',()=>{state.preferences.name=$('displayName').value.trim();state.preferences.currency=$('currency').value;persist();toast('Preferences saved');});$('resetData').addEventListener('click',()=>{if(!confirm('Delete all Northstar data in this browser? This cannot be undone.'))return;if(!confirm('Last check: have you exported a backup if you need one?'))return;state=defaults();persist();$('backupStatus').textContent='Workspace reset.';toast('Workspace reset');});
function init(){const todayInputs=['txDate','receiptDate'];todayInputs.forEach(id=>$(id).value=today());$('displayName').value=state.preferences.name||'';$('currency').value=state.preferences.currency||'NZD';$('offlineStatus').textContent=('serviceWorker'in navigator)?'Available':'Not supported here';const d=new Date();$('dateLine')?.textContent;renderAll();}
// Home header's date line is created in the existing markup as a concise local date.
const headerDate=document.createElement('div');headerDate.className='muted';headerDate.style.fontSize='11px';headerDate.textContent=new Date().toLocaleDateString('en-NZ',{weekday:'long',day:'numeric',month:'long'});document.querySelector('.brand').after(headerDate);
init();
})();
